// 账单生成后该月累计与账单用量已经固定，晚到的新事件不会
// 重新计算账单。拒收不消耗事件标识 e2。
_, err = s.RecordEvent(meter.Event{
    AccountID: accountID,
    EventID:   "e2",
    At:        mustParseTime("2026-01-20T00:00:00Z"),
    Quantity:  1,
