fmt.Printf("event e2    errMonthBilled=%t\n", errors.Is(err, meter.ErrMonthBilled))

// 被拒收的事件没有累计：一月用量仍是 13。
usage, err = s.MonthlyUsage(accountID, jan)
if err != nil {
